window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[144]={"id":"144","numero":144,"titre":"Deuil normal et pathologique","objectifs":[{"id":"144-1","rang":"A","rubrique":"Définition","titre":"Connaître les caractéristiques d’un deuil normal et pathologique","contenu":"<div class=\"notion-course\"><p>Le <strong>deuil</strong> désigne l’ensemble des réactions émotionnelles, cognitives et comportementales face au décès d’une personne proche. C’est une réaction <strong>« normale »</strong> pour la majorité des personnes. Ces réactions dépendent du contexte socio-culturel : la douleur vécue par la personne endeuillée varie selon les valeurs, les habitudes de vie et les principes d’un groupe ou d’une société.</p>\n\n      <p><strong>Réactions du deuil normal</strong> — réactions émotionnelles pouvant être entremêlées ou simultanées :</p>\n      <table>\n        <thead><tr><th>Phase</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-yellow_bg\">Choc de la perte</span></td><td>Abattement ; état de sidération affective (± symptômes dissociatifs)</td></tr>\n          <tr><td>Sentiment d’absence</td><td>Lié à l’état de manque du défunt : <span class=\"nc-blue nc-bold\">angoisse</span>, <span class=\"nc-blue nc-bold\">colère</span>, <span class=\"nc-blue nc-bold\">désespoir</span>, <span class=\"nc-blue nc-bold\">culpabilité</span></td></tr>\n          <tr><td><span class=\"nc-yellow_bg\">Tristesse</span></td><td><span class=\"nc-yellow_bg\">Tristesse</span></td></tr>\n          <tr><td><span class=\"nc-green_bg\">Réorganisation</span></td><td>Acceptation de la réalité de la perte ; adaptation à une vie quotidienne réinvestie dans un monde où le défunt est absent</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Deuil normal.</strong> <span class=\"nc-green_bg nc-bold\">Processus</span> <span class=\"nc-green_bg\">évoluant généralement vers l’apaisement</span> et la <span class=\"nc-green_bg\">réorganisation</span>. Le Collège rapporte une moyenne de <strong><span class=\"nc-pink nc-bold\">2 à 3 mois</span></strong>, variable selon le lien d’attachement, l’âge du défunt et les circonstances du décès. <strong>Ce repère n’est ni une date limite ni un critère diagnostique</strong> : une <span class=\"nc-yellow_bg\">tristesse</span> persistante ou réactivée à une date anniversaire peut rester compatible avec une adaptation progressive. Les réactions décrites ne constituent pas des étapes obligatoires à franchir dans un ordre fixe.</p>\n\n      <p><strong>Deuil pathologique</strong> — quatre formes :</p>\n      <ul>\n        <li><strong><span class=\"nc-yellow_bg\">Deuil prolongé</span></strong> (détaillé ci-dessous).</li>\n        <li><strong><span class=\"nc-yellow_bg\">Épisode dépressif caractérisé</span></strong> : trouble psychiatrique le <strong>plus fréquent</strong> en contexte de deuil.</li>\n        <li><strong><span class=\"nc-orange_bg\">Troubles anxieux</span></strong> : en particulier le trouble anxieux généralisé.</li>\n        <li><strong><span class=\"nc-orange_bg\">TSPT</span> :</strong> rechercher une exposition traumatique qualifiante et l’ensemble des critères ; une annonce ressentie comme brutale ne suffit pas.</li>\n      </ul>\n      <p>Le deuil est par ailleurs un facteur de décompensation de tous les troubles psychiatriques préexistants et des usages de substance.</p>\n\n      <div class=\"callout\"><p><strong>Risque suicidaire.</strong> Le deuil augmente le <span class=\"nc-red_bg\">risque de</span> <span class=\"nc-red_bg nc-bold\">suicide</span>, surtout dans les premiers jours. Le Collège cite, pour la première semaine, une multiplication par plus de 50 chez l’homme et par 10 chez la <span class=\"nc-pink_bg\">femme</span> : ce sont des données de groupe, pas un calcul du risque individuel. Un désir de « <span class=\"nc-green_bg nc-bold\">rejoindre le défunt</span> » impose une exploration directe des idées, de l’intention, du scénario, de l’accès aux moyens, des antécédents et des protections. Il ne doit jamais être banalisé comme un signe rassurant de deuil normal.</p></div>\n\n      <div class=\"callout\"><p><strong>Deuil et trouble de l’adaptation.</strong> Un deuil normal ne justifie pas un diagnostic de trouble de l’adaptation. Devant une souffrance qui devient pathologique, rechercher les critères du trouble en cause : <span class=\"nc-yellow_bg\">deuil prolongé</span>, <span class=\"nc-yellow_bg\">épisode dépressif caractérisé</span>, trouble anxieux ou trouble de stress post-traumatique. La seule présence d’un décès ne suffit pas à choisir une étiquette diagnostique.</p></div>\n\n      <p><strong>Le <span class=\"nc-yellow_bg\">deuil prolongé</span></strong></p>\n      <table><thead><tr><th>Dimension</th><th>Évaluation clinique</th></tr></thead><tbody><tr><td>Définition</td><td>Persistance d’un manque envahissant ou de <span class=\"nc-green_bg\">préoccupations</span> centrées sur le défunt, avec difficulté à se réorganiser après la <span class=\"nc-blue_bg nc-bold\">perte</span>. Évaluer souffrance, comportement, émotions, cognition et fonctionnement.</td></tr><tr><td>Manifestations</td><td><span class=\"nc-blue_bg\">Manque intense</span> ; <span class=\"nc-red nc-bold\">difficulté marquée à accepter le décès</span> ; incrédulité ; évitement de ce qui rappelle la perte ; douleur émotionnelle intense ; anesthésie affective ; solitude ; perturbation de l’identité ; <span class=\"nc-red nc-bold\">sentiment que la vie n’a plus de sens</span> ; difficulté à réinvestir les relations et activités. Chez le jeune, les <span class=\"nc-green_bg\">préoccupations</span> peuvent porter sur les circonstances du décès.</td></tr><tr><td>Temporalité DSM-5-TR</td><td>Décès datant d’au moins <strong>12 mois chez l’adulte</strong> ou <strong>6 mois chez <span class=\"nc-pink_bg nc-bold\">l’enfant</span> et l’adolescent</strong>. Les symptômes requis sont présents presque chaque jour <strong>au moins durant le dernier mois</strong>. Ne pas confondre le délai écoulé depuis le décès et la fréquence récente des symptômes.</td></tr><tr><td>Critères associés</td><td><span class=\"nc-blue_bg\">Manque intense</span> et/ou préoccupation concernant le défunt, plus au moins trois manifestations associées parmi les huit domaines du DSM-5-TR : identité, incrédulité, évitement, douleur émotionnelle, difficulté de réinvestissement, anesthésie affective, perte de sens, solitude.</td></tr><tr><td>Retentissement et contexte</td><td>Souffrance cliniquement significative ou altération du fonctionnement ; durée et intensité dépassant les normes sociales, culturelles ou religieuses de la personne. Vérifier que le tableau n’est pas mieux expliqué par un autre trouble, une substance ou une affection somatique.</td></tr><tr><td>Classifications</td><td>Le seuil de 12 mois chez l’adulte correspond au DSM-5-TR. La CIM-11 retient un seuil minimal de 6 mois, également associé au retentissement et au dépassement des normes culturelles. Toujours nommer la classification utilisée.</td></tr></tbody></table><div class=\"callout\"><p><strong>Ne pas attendre le seuil diagnostique pour aider.</strong> Une souffrance majeure, une incapacité à fonctionner, un épisode dépressif ou un danger suicidaire nécessitent une prise en charge dès leur repérage. <span class=\"nc-yellow_bg\">Deuil prolongé</span> et épisode dépressif peuvent coexister si chacun remplit ses critères.</p></div>\n\n      <p><strong>Deuil normal vs <span class=\"nc-yellow_bg\">épisode dépressif caractérisé</span></strong> — l’EDC en contexte de deuil est similaire à un EDC survenant hors deuil : même pronostic, même durée d’épisode, mêmes comorbidités, même réponse aux traitements, mêmes facteurs de risque (antécédents familiaux et personnels de troubles psychiatriques, troubles de l’humeur en particulier).</p>\n      <table>\n        <thead><tr><th>Critère</th><th>Deuil normal</th><th><span class=\"nc-yellow_bg\">Épisode dépressif caractérisé</span></th></tr></thead>\n        <tbody>\n          <tr><td>Affect prédominant</td><td><span class=\"nc-blue_bg\">Sentiment de</span> <span class=\"nc-blue_bg nc-bold\">vide</span> <span class=\"nc-blue_bg\">et de</span> <span class=\"nc-blue_bg nc-bold\">perte</span>, lié à l’état de manque du défunt</td><td><span class=\"nc-orange_bg\">Humeur dépressive persistante</span></td></tr>\n          <tr><td>Émotions négatives</td><td>Diminuent d’intensité avec le temps ; surviennent par <strong>vagues</strong> associées à des pensées ou <span class=\"nc-green_bg\">souvenirs</span> du défunt</td><td><strong><span class=\"nc-red nc-bold\">Intenses</span></strong>, avec une douleur morale majeure et persistante, non liée à des pensées spécifiques</td></tr>\n          <tr><td><span class=\"nc-pink nc-bold\">Émotions positives</span></td><td>La douleur peut être accompagnée d’<span class=\"nc-pink nc-bold\">émotions positives</span> et d’humour</td><td><span class=\"nc-orange_bg\">Anhédonie</span> : <span class=\"nc-orange_bg\">incapacité à anticiper la joie ou le plaisir</span></td></tr>\n          <tr><td>Pensées</td><td><span class=\"nc-green_bg\">Préoccupations</span> et <span class=\"nc-green_bg\">souvenirs</span> concernant la personne décédée</td><td>Ruminations autocritiques, <span class=\"nc-blue_bg\">fatalistes</span>, <span class=\"nc-blue_bg\">culpabilisatrices</span>, <span class=\"nc-blue_bg\">pessimistes</span></td></tr>\n          <tr><td>Estime de soi</td><td>Généralement <strong><span class=\"nc-green nc-bold\">préservée</span></strong></td><td><span class=\"nc-red nc-bold\">Faible</span> voire <span class=\"nc-red nc-bold\">effondrée</span> : <span class=\"nc-red nc-bold\">sentiments de dévalorisation et de dégoût de soi</span></td></tr>\n          <tr><td>Idées de <span class=\"nc-red_bg nc-bold\">suicide</span></td><td>Si présentes : <span class=\"nc-green_bg\">idée de</span> <strong><span class=\"nc-green_bg nc-bold\">rejoindre le défunt</span></strong></td><td>Associées au <span class=\"nc-blue_bg\">sentiment de</span> dévalorisation, d’indignité ou d’incapacité à faire face à la douleur</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Spécificités du deuil périnatal</strong></p>\n      <p>La perte d’un fœtus ou d’un nouveau-né est un <strong>deuil à part entière</strong> : aucune perte d’un bébé n’est à minimiser, quelles que soient les modalités du décès ou la durée de vie partagée. Elle renvoie les parents aux mêmes problématiques que la perte d’un enfant plus âgé et est souvent décrite comme « l’événement le plus traumatique qui soit » : annihilation de l’avenir rêvé, rupture dans l’ordre générationnel, <span class=\"nc-red nc-bold\">effraction du sentiment de compétence parentale</span>.</p>\n      <table>\n        <thead><tr><th>Dimension</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td>Difficultés spécifiques</td><td><span class=\"nc-blue_bg\">Collusion des temps du naître et du mourir</span> ; perte du statut de parent en devenir (<span class=\"nc-red nc-bold\">sentiment de faillite</span>) ; impossibilité de la rencontre si décès in utero (blessure narcissique, honte, <span class=\"nc-red nc-bold\">culpabilité</span>) ; sentiment d’irréalité ; <span class=\"nc-red_bg\">crainte d’une future grossesse</span> ; <span class=\"nc-red nc-bold\">intensité du sentiment de culpabilité</span> (surtout étiologies génétiques et malformatives) ; sentiment d’incompréhension par l’entourage</td></tr>\n          <tr><td>Vécu selon les circonstances</td><td><strong>Décès d’un jumeau :</strong> sentiments contradictoires de joie et de <span class=\"nc-yellow_bg\">tristesse</span>, d’élan de vie et de mort<br><strong>Fausse couche / décès inopiné :</strong> aucun temps de préparation psychique<br><strong>IVG / IMG :</strong> ambivalence intense entre <span class=\"nc-green nc-bold\">soulagement</span> et <span class=\"nc-red nc-bold\">culpabilité</span> ; peur d’être jugés ; conflits possibles dans le couple ou avec l’entourage</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble dépressif · 353 — Risque et conduite suicidaire</em></p><h4>Distinguer les complications sans les rendre exclusives</h4><ul><li><strong><span class=\"nc-yellow_bg\">Épisode dépressif caractérisé</span> :</strong> humeur dépressive et/ou <span class=\"nc-orange_bg\">anhédonie</span> persistantes, autres symptômes, durée et retentissement répondant aux critères de l’EDC. Un deuil récent n’exclut pas ce diagnostic : ne pas attendre 6 ou 12 mois. Le tableau comparatif oriente mais ne remplace pas l’entretien diagnostique.</li><li><strong><span class=\"nc-orange_bg\">TSPT</span> :</strong> rechercher une exposition traumatique qualifiante, des reviviscences, évitements et autres symptômes répondant aux critères. Une annonce ressentie comme brutale n’établit pas à elle seule un <span class=\"nc-orange_bg\">TSPT</span>.</li><li><strong>Autres troubles :</strong> <span class=\"nc-orange_bg\">troubles anxieux</span>, décompensation d’un trouble psychiatrique préexistant ou d’un trouble de l’usage de substances. Les diagnostics associés sont recherchés même si un <span class=\"nc-yellow_bg\">deuil prolongé</span> est identifié.</li></ul><p>Le tableau comparatif deuil normal/EDC reprend les dimensions du <strong>tableau 1 original du Collège, p.137</strong>. Il est consultable dans les ressources originales de cet item. Les parcours interactifs ATLAS sont des synthèses cliniques distinctes de ce document.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941812a92b7e05e60d437c5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Deuil normal et pathologique (144)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf#page=136\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e éd. 2024, item 144, p.135–138</a></li><li><a href=\"https://www.psychiatry.org/patients-families/prolonged-grief-disorder\" target=\"_blank\" rel=\"noopener noreferrer\">American Psychiatric Association · Deuil prolongé, critères DSM-5-TR et soins, révision août 2025</a></li><li><a href=\"https://onlinelibrary.wiley.com/doi/full/10.1002/wps.20823\" target=\"_blank\" rel=\"noopener noreferrer\">Prigerson et al. · Validation des critères DSM-5-TR du deuil prolongé, World Psychiatry 2021</a></li><li><a href=\"https://www.psychiatry.org/getmedia/b68a5776-f88c-45c7-9535-fd219d7aa5cb/APA-DSM5TR-Update-September-2025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">American Psychiatric Association · Mises à jour du DSM-5-TR, compilation septembre 2025</a></li><li><a href=\"https://www.ameli.fr/medecin/sante-prevention/pathologies/episode-depressif-caracterise-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Épisode dépressif caractérisé de l’adulte, recommandations HAS, décembre 2025</a></li></ul><p>Précisions ajoutées : réactions non linéaires ; moyenne 2–3 mois non normative ; délais DSM-5-TR et CIM-11 distingués ; diagnostic non fondé sur la durée seule ; possibilité de comorbidité EDC ; risque suicidaire non banalisé. Les spécificités périnatales du cours Notion sont conservées.</p></details><details data-lisa-review=\"psyfinal\"><summary>Situations de départ · LiSA EDN 2026 vérifié</summary><p>Liens de la fiche et attendus de chaque situation relus le 14 octobre 2026. Les repères suivants sont des synthèses des attendus, pas une validation de couverture intégrale.</p><ul><li><a href=\"https://livret.uness.fr/lisa/2026/D%C3%A9c%C3%A8s_SDD-237\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>SDD 237 — Décès</strong></a> : Accompagner l’annonce avec empathie, écouter les proches et repérer les facteurs de risque de deuil pathologique.</li><li><a href=\"https://livret.uness.fr/lisa/2026/Accompagnement_global_d%27un_aidant_SDD-330\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>SDD 330 — Accompagnement global d’un aidant</strong></a> : Évaluer le vécu, la charge et la souffrance de l’aidant ; repérer ses besoins médicaux, psychologiques et sociaux et proposer un soutien.</li></ul><p><strong>Portée de cette fiche.</strong> La fiche travaille le deuil et le soutien des proches. Le constat de décès, les démarches administratives et l’ensemble des besoins de l’aidant relèvent d’autres enseignements.</p><p><a href=\"https://livret.uness.fr/lisa/2026/Deuil_normal_et_pathologique\" target=\"_blank\" rel=\"noopener noreferrer\">Voir les correspondances officielles de l’item dans LiSA ↗</a></p></details>","frequence":2},{"id":"144-2","rang":"B","rubrique":"Étiologies","titre":"Connaître les facteurs de risque de complications du deuil","contenu":"<div class=\"notion-course\"><p><span>Les</span> <span>facteurs de <span class=\"nc-red_bg\">risque de</span> deuil pathologique</span> (complications du deuil) sont régulièrement tombés à l’EDN. Ils se répartissent en <strong>trois catégories</strong>.</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th><span>Facteurs de risque</span></th></tr></thead>\n        <tbody>\n          <tr><td>Liés au <strong>défunt</strong></td><td><span><span class=\"nc-pink_bg\">Mort d’une personne</span> <span class=\"nc-pink_bg nc-bold\">plus</span> <span class=\"nc-pink_bg nc-bold\">jeune</span></span> ; <span><span class=\"nc-pink_bg\">décès du</span> <span class=\"nc-pink_bg nc-bold\">conjoint</span> <span class=\"nc-pink_bg\">ou de</span> <span class=\"nc-pink_bg nc-bold\">l’enfant</span></span></td></tr>\n          <tr><td>Liés aux <strong>circonstances du décès</strong></td><td><span><span class=\"nc-red_bg\">Mort par suicide</span></span> ; <span><span class=\"nc-red_bg\">mort soudaine</span>, <span class=\"nc-red_bg\">inattendue</span>, <span class=\"nc-red_bg\">violente</span></span></td></tr>\n          <tr><td>Liés à l’<strong>endeuillé</strong></td><td><span><span class=\"nc-pink_bg\">Âge jeune</span></span>, <span><span class=\"nc-pink_bg\">femme</span></span> ; <span><span class=\"nc-pink_bg\">relation d’attachement</span></span><span class=\"nc-pink_bg\"> avec le défunt</span> ; <span><span class=\"nc-yellow_bg\">répétition de deuil</span></span> ; <span>antécédents personnels de trouble psychiatrique</span>, <span class=\"nc-orange_bg\">stratégie d’ajustement au stress réduite</span> ; <span><span class=\"nc-blue_bg\">sentiment de culpabilité</span></span>, <span class=\"nc-blue_bg\">manque de compréhension de la situation</span> ; <span><span class=\"nc-brown_bg\">manque de soutien social</span></span>, <span><span class=\"nc-brown_bg\">précarité sociale</span></span>, <span><span class=\"nc-brown_bg\">absence de rituels de deuil</span></span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout\"><p><strong>Piège EDN.</strong> Le caractère récent du décès ne suffit pas à qualifier un deuil de pathologique, ni à prédire à lui seul un <span class=\"nc-yellow_bg\">deuil prolongé</span>. En revanche, les premiers jours sont une période de vigilance suicidaire accrue : ne pas confondre <span class=\"nc-red_bg\">risque de</span> <span class=\"nc-yellow_bg\">deuil prolongé</span> et urgence suicidaire.</p></div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 353 — Risque et conduite suicidaire</em></p><h4>Compléter l’évaluation et adapter le suivi</h4><ul><li><strong>Circonstances :</strong> préciser la perception de la souffrance du proche avant son décès, les pertes antérieures, l’impossibilité de se préparer ou de participer aux rituels.</li><li><strong>Ressources :</strong> identifier qui peut être présent, les capacités d’ajustement, les conditions de vie, le fonctionnement quotidien et l’accès à une aide. Un facteur de risque n’est pas une fatalité ni un critère diagnostique.</li><li><strong>Antécédents :</strong> rechercher dépression, trouble bipolaire, tentative de <span class=\"nc-red_bg nc-bold\">suicide</span>, autres troubles psychiatriques et usages de substances. Pour l’EDC, les antécédents personnels et familiaux de trouble de l’humeur comptent.</li><li><strong>Lecture EDN :</strong> la liste ci-dessus reprend celle du Collège, qui cite l’<span class=\"nc-pink_bg\">âge jeune</span>. Les associations observées avec l’âge varient selon les études ; l’âge ne doit pas servir à écarter une personne âgée du suivi.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941812a92b7e05e60d437c5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Deuil normal et pathologique (144)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf#page=136\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e éd. 2024, item 144, p.135–138</a></li><li><a href=\"https://www.psychiatry.org/patients-families/prolonged-grief-disorder\" target=\"_blank\" rel=\"noopener noreferrer\">American Psychiatric Association · Deuil prolongé, critères DSM-5-TR et soins, révision août 2025</a></li></ul><p>Ajout du vécu de la souffrance du défunt, des ressources et de la fonction pratique des facteurs de risque. Nuance de la mention « deuil récent » ; liste EDN conservée et âge présenté sans déterminisme.</p></details>","frequence":4},{"id":"144-3","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’un deuil normal et pathologique","contenu":"<div class=\"notion-course\"><p>La <strong>majorité des personnes en deuil n’ont pas besoin de prise en charge médicale</strong> : la <span>phase aiguë</span> du deuil est intense mais se résout progressivement à mesure que la réalité de la perte est intégrée dans la vie quotidienne.</p>\n\n      <p><strong>CAT en consultation — prise en charge de la personne en deuil</strong></p>\n      <ul>\n        <li><span><span class=\"nc-green_bg\">Psychothérapie de soutien</span></span> et <span><span class=\"nc-green_bg\">écoute empathique</span></span>.</li>\n        <li><strong>Identifier et expliquer</strong> le <span class=\"nc-green_bg nc-bold\">processus</span> normal du deuil, notamment en termes de <span><span class=\"nc-green_bg\">réorganisation</span></span>.</li>\n        <li><strong><span class=\"nc-green_bg\">Pas de </span><span><span class=\"nc-green_bg\">surmédicalisation</span></span></strong><span class=\"nc-green_bg\"> du deuil normal</span> : bien distinguer le <span>deuil normal</span> du <span>deuil pathologique</span>.</li>\n        <li><span class=\"nc-blue_bg\">Insister sur l’importance de </span><strong><span class=\"nc-blue_bg\">partager sa souffrance</span></strong> (<span class=\"nc-blue_bg\">amis</span>, <span class=\"nc-blue_bg\">famille</span>, <span><span class=\"nc-blue_bg\">associations de soutien</span></span>…).</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong><span class=\"nc-yellow_bg\">Deuil prolongé</span>.</strong> Le traitement du <span><span class=\"nc-yellow_bg\">deuil prolongé</span></span> repose sur une psychothérapie de type <span><span class=\"nc-green_bg nc-bold\">thérapie comportementale et cognitive</span> (TCC)</span>.</div>\n\n      <p><strong>Accompagnement spécialisé du deuil périnatal</strong></p>\n      <ul>\n        <li><strong>Restaurer le <span class=\"nc-blue_bg\">sentiment de</span> compétence parentale</strong>, aussi brève qu’ait été la vie de <span class=\"nc-pink_bg nc-bold\">l’enfant</span>.</li>\n        <li>Proposer un accompagnement du deuil dans une dimension <strong>sociale et associative</strong> (<span>groupes de parole</span> entre pairs).</li>\n        <li><span class=\"nc-blue_bg\">Proposer un </span><strong><span><span class=\"nc-blue_bg\">accompagnement social</span></span></strong><span class=\"nc-blue_bg\"> pour </span><span><span class=\"nc-blue_bg\">les</span></span><span class=\"nc-blue_bg\"> démarches administratives</span> (<span class=\"nc-blue_bg\">déclaration de décès</span>, congés maternité / paternité, <span class=\"nc-blue_bg\">obsèques</span>…).</li>\n        <li>Ouvrir à chacun un <strong>espace individualisé d’expression</strong> de sa souffrance, respectueux du vécu de chacun.</li>\n        <li>Penser à la <strong>fratrie</strong> (exposée à la perte, au chagrin parental, à un sentiment d’abandon <span class=\"nc-blue_bg\">et de</span> culpabilité, à l’<span class=\"nc-blue nc-bold\">angoisse</span> de mourir) et aux <strong>grands-parents</strong> (« double peine » : chagrin de la perte de leur petit-enfant + impuissance à protéger leur propre enfant).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble dépressif · 140 — Soins palliatifs 2 - accompagnement de la personne et de son entourage · 353 — Risque et conduite suicidaire</em></p><h4>Évaluation médicale et suivi</h4><ol><li><strong>Rechercher immédiatement un danger :</strong> idées de mort <span class=\"nc-pink_bg\">ou de</span> <span class=\"nc-red_bg nc-bold\">suicide</span>, intention, scénario, moyens accessibles, passage à l’acte récent, agitation, psychose, intoxication, isolement ou incapacité à assurer les besoins essentiels. Le contenu « <span class=\"nc-green_bg nc-bold\">rejoindre le défunt</span> » ne dispense jamais de cette évaluation.</li><li><strong>Établir la chronologie et le retentissement :</strong> date et circonstances du décès, lien au défunt, trajectoire de la souffrance, sommeil, alimentation, activités, soutien familial et social, antécédents et traitements.</li><li><strong>Examiner :</strong> examen psychique ; examen somatique complet si complication ou plainte, notamment cardiovasculaire comme le rappelle le Collège. Les examens complémentaires sont guidés par les symptômes et le terrain ; aucun bilan ne diagnostique un <span class=\"nc-yellow_bg\">deuil prolongé</span>.</li><li><strong>Prévoir la continuité :</strong> proposer un contact ou un rendez-vous adapté à la souffrance et aux ressources, réévaluer la dynamique et le risque suicidaire. Avancer la réévaluation en cas d’aggravation, de retrait majeur ou de difficulté à maintenir les activités essentielles.</li></ol><h4>Indications thérapeutiques selon le tableau</h4><table><thead><tr><th>Situation</th><th>Conduite</th></tr></thead><tbody><tr><td>Deuil normal</td><td><span class=\"nc-green_bg\">Écoute empathique</span>, explications, soutien de l’entourage, rituels souhaités et <span class=\"nc-blue_bg\">associations de soutien</span>. Respecter le rythme, les croyances et les choix. Pas de prescription d’antidépresseur pour le seul deuil normal ; pas de psychotrope systématique.</td></tr><tr><td><span class=\"nc-yellow_bg\">Deuil prolongé</span></td><td>Orienter vers une psychothérapie ciblée, notamment de type <span class=\"nc-green_bg nc-bold\">thérapie comportementale et cognitive</span>. Travailler l’intégration de la réalité de la perte et le réinvestissement de la vie ; traiter les troubles associés. Un antidépresseur n’est pas un traitement spécifique automatique du <span class=\"nc-yellow_bg\">deuil prolongé</span>.</td></tr><tr><td>EDC associé</td><td>Même prise en charge qu’un EDC hors deuil, selon sévérité, risque, antécédents et préférences. Psychothérapie ; antidépresseur envisageable dans un EDC modéré et indiqué d’emblée avec avis psychiatrique rapide dans un EDC sévère. Rechercher une bipolarité avant prescription et organiser le suivi de la tolérance et du risque suicidaire.</td></tr><tr><td>Autre trouble psychiatrique</td><td>Soins propres au diagnostic : trouble anxieux, <span class=\"nc-orange_bg\">TSPT</span>, trouble de l’usage de substances ou décompensation d’un trouble préexistant. Ne pas attribuer automatiquement tous les symptômes au deuil.</td></tr><tr><td>Danger suicidaire ou défaillance des besoins essentiels</td><td>Évaluation urgente et protection proportionnée. Si danger immédiat, ne pas laisser la personne seule, sécuriser l’accès aux moyens dangereux et organiser les secours/soins urgents. Hospitalisation selon évaluation clinique ; rechercher le consentement et respecter le cadre légal si soins sans consentement nécessaires.</td></tr></tbody></table><h4>Personnaliser l’accompagnement périnatal</h4><p>Les propositions précédentes se construisent avec les parents : ne pas imposer un récit, un rituel ni une manière de vivre le deuil. Respecter les vécus différents au sein du couple ; une ambivalence ou un <span class=\"nc-green nc-bold\">soulagement</span> ne préjuge pas d’un trouble. Coordonner maternité, médecin traitant, équipe psychologique et soutien social selon les besoins. Les démarches administratives dépendent de la situation obstétricale et doivent être expliquées individuellement.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941812a92b7e05e60d437c5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Deuil normal et pathologique (144)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf#page=136\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e éd. 2024, item 144, p.135–138</a></li><li><a href=\"https://www.psychiatry.org/patients-families/prolonged-grief-disorder\" target=\"_blank\" rel=\"noopener noreferrer\">American Psychiatric Association · Deuil prolongé, critères DSM-5-TR et soins, révision août 2025</a></li><li><a href=\"https://www.ameli.fr/medecin/sante-prevention/pathologies/episode-depressif-caracterise-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Épisode dépressif caractérisé de l’adulte, recommandations HAS, décembre 2025</a></li></ul><p>Compléments de prise en charge : évaluation systématique du risque, examen clinique, surveillance, soins des complications, indications des antidépresseurs limitées au trouble identifié, protection en urgence. Le contenu périnatal détaillé de Notion est conservé.</p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Le temps seul ne fait pas le diagnostic","contenu":"<div class=\"notion-course\"><p>Ni trois mois de <span class=\"nc-yellow_bg\">tristesse</span> ni douze mois depuis le décès ne suffisent : évaluer symptômes, retentissement, culture et trajectoire.</p></div>"},{"type":"piege","titre":"Ne pas confondre les deux horloges","contenu":"<div class=\"notion-course\"><p>DSM-5-TR : décès <span class=\"nc-pink nc-bold\">≥12 mois</span> chez l’adulte, ≥6 mois chez le mineur ; symptômes requis presque quotidiens au moins durant le dernier mois.</p></div>"},{"type":"piege","titre":"Rejoindre le défunt reste un signal à explorer","contenu":"<div class=\"notion-course\"><p>Le thème des idées suicidaires ne diminue pas la nécessité d’évaluer l’intention et de protéger selon le risque.</p></div>"},{"type":"piege","titre":"Le deuil n’exclut pas un EDC","contenu":"<div class=\"notion-course\"><p>EDC et <span class=\"nc-yellow_bg\">deuil prolongé</span> peuvent coexister ; traiter chaque trouble selon ses indications.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Dater le décès et apprécier l’évolution, le contexte culturel et le fonctionnement.</li><li>Dès la première rencontre, évaluer le risque suicidaire et les besoins essentiels.</li><li>Rechercher EDC, <span class=\"nc-orange_bg\">TSPT</span>, anxiété, substances et décompensation d’un trouble préexistant.</li><li>Pour le <span class=\"nc-yellow_bg\">deuil prolongé</span>, préciser DSM-5-TR ou CIM-11 et vérifier tous les critères.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Deuil normal : écoute, soutien et ressources ; pas de prescription systématique.</li><li><span class=\"nc-yellow_bg\">Deuil prolongé</span> : psychothérapie ciblée, notamment TCC, et soins des comorbidités.</li><li>EDC : prise en charge habituelle selon sévérité ; le deuil ne contre-indique pas un traitement indiqué.</li><li>Danger suicidaire : protection et prise en charge urgente sans attendre un seuil de durée.</li><li>Périnatal : accompagnement personnalisé des parents et de leur entourage.</li></ul></div>","Examens complémentaires":"<div class=\"notion-course\"><ul><li>Entretien et examen clinique ; examen somatique adapté, notamment en cas de complication.</li><li>Biologie, ECG ou autres examens uniquement selon symptômes, terrain et traitements envisagés.</li><li>Aucun examen complémentaire ne confirme à lui seul un <span class=\"nc-yellow_bg\">deuil prolongé</span>.</li></ul></div>"},"cards":[{"i":"f61503c4db7c","n":144,"o":"144-1","u":"Définition","t":"Connaître les caractéristiques d’un deuil normal et pathologique","q":"Après un décès, la tristesse dépasse 3 mois. Cela suffit-il pour parler de deuil pathologique ?","a":"<div class=\"notion-course\"><ul><li>Non : la moyenne de <span class=\"nc-pink nc-bold\">2 à 3 mois</span> citée par le Collège n’est pas un seuil diagnostique.</li><li>Évaluer évolution, retentissement, contexte culturel et critères d’un éventuel trouble.</li></ul></div>"},{"i":"a13d66236ec7","n":144,"o":"144-1","u":"Définition","t":"Connaître les caractéristiques d’un deuil normal et pathologique","q":"Les réactions de choc, d’absence, de tristesse et de réorganisation suivent-elles un ordre obligatoire ?","a":"<div class=\"notion-course\"><ul><li>Non : elles peuvent se mêler ou survenir simultanément.</li><li>Le deuil normal tend progressivement vers l’apaisement et le réinvestissement de la vie.</li></ul></div>"},{"i":"85fcdf47aef8","n":144,"o":"144-1","u":"Définition","t":"Connaître les caractéristiques d’un deuil normal et pathologique","q":"Une veuve garde des moments de plaisir et une estime de soi préservée, avec tristesse par vagues liée aux souvenirs. Quel tableau évoquer ?","a":"<div class=\"notion-course\"><ul><li>Un deuil normal, à confronter à la trajectoire et au retentissement.</li><li>Une <span class=\"nc-yellow_bg\">tristesse</span> persistante généralisée, une <span class=\"nc-orange_bg\">anhédonie</span> et une dévalorisation orienteraient vers un EDC.</li></ul></div>"},{"i":"6f803abf7980","n":144,"o":"144-1","u":"Définition","t":"Connaître les caractéristiques d’un deuil normal et pathologique","q":"Un homme dit vouloir « rejoindre son épouse décédée ». Peut-on banaliser cette pensée comme un deuil normal ?","a":"<div class=\"notion-course\"><ul><li>Non. Explorer directement idées suicidaires, intention, scénario, accès aux moyens, antécédents et protections.</li><li>Organiser protection et urgence selon le risque actuel.</li></ul></div>"},{"i":"8efadec5002f","n":144,"o":"144-1","u":"Définition","t":"Connaître les caractéristiques d’un deuil normal et pathologique","q":"Quel délai depuis le décès est requis pour un deuil prolongé selon le DSM-5-TR ?","a":"<div class=\"notion-course\"><ul><li>Adulte : au moins 12 mois.</li><li>Enfant et adolescent : au moins 6 mois.</li><li>Le délai seul ne suffit pas au diagnostic.</li></ul></div>"},{"i":"66c23d4160c9","n":144,"o":"144-1","u":"Définition","t":"Connaître les caractéristiques d’un deuil normal et pathologique","q":"Dans le DSM-5-TR, faut-il confondre les 12 mois depuis le décès et la durée des symptômes quotidiens ?","a":"<div class=\"notion-course\"><ul><li>Non : les 12 mois sont le délai minimal depuis le décès chez l’adulte.</li><li>Les symptômes requis sont presque quotidiens au moins durant le dernier mois.</li></ul></div>"},{"i":"0b2c4b6d5419","n":144,"o":"144-1","u":"Définition","t":"Connaître les caractéristiques d’un deuil normal et pathologique","q":"Quel noyau symptomatique rechercher devant un deuil prolongé ?","a":"<div class=\"notion-course\"><ul><li>Un <span class=\"nc-blue_bg\">manque intense</span> du défunt et/ou des <span class=\"nc-green_bg\">préoccupations</span> envahissantes concernant celui-ci.</li><li>Associer manifestations complémentaires, souffrance ou retentissement significatif et dépassement des normes culturelles.</li></ul></div>"},{"i":"b0696672bb19","n":144,"o":"144-1","u":"Définition","t":"Connaître les caractéristiques d’un deuil normal et pathologique","q":"Un EDC et un deuil prolongé peuvent-ils être diagnostiqués chez la même personne ?","a":"<div class=\"notion-course\"><ul><li>Oui, si les critères de chacun sont remplis.</li><li>Le <span class=\"nc-yellow_bg\">deuil prolongé</span> ne dispense pas de rechercher dépression et risque suicidaire.</li></ul></div>"},{"i":"95280e194f94","n":144,"o":"144-1","u":"Définition","t":"Connaître les caractéristiques d’un deuil normal et pathologique","q":"Un décès récent interdit-il de diagnostiquer un épisode dépressif caractérisé ?","a":"<div class=\"notion-course\"><ul><li>Non : retenir les critères de l’EDC et son retentissement.</li><li>Ne pas attendre le délai de 6 ou 12 mois propre au <span class=\"nc-yellow_bg\">deuil prolongé</span>.</li></ul></div>"},{"i":"1dd40c4e25cb","n":144,"o":"144-1","u":"Définition","t":"Connaître les caractéristiques d’un deuil normal et pathologique","q":"Quel seuil minimal la CIM-11 utilise-t-elle pour le deuil prolongé ?","a":"<div class=\"notion-course\"><ul><li>Au moins 6 mois, avec retentissement significatif et réaction dépassant les normes sociales, culturelles ou religieuses.</li><li>Toujours préciser la classification : DSM-5-TR adulte = au moins 12 mois depuis le décès.</li></ul></div>"},{"i":"e7eb99746959","n":144,"o":"144-2","u":"Étiologies","t":"Connaître les facteurs de risque de complications du deuil","q":"Une patiente a perdu brutalement son enfant par suicide. Quels facteurs liés au décès augmentent le risque de complications ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-red_bg\">Mort soudaine</span>, <span class=\"nc-red_bg\">violente</span> ou par <span class=\"nc-red_bg nc-bold\">suicide</span>.</li><li>Décès d’un enfant, personne <span class=\"nc-pink_bg nc-bold\">plus</span> <span class=\"nc-pink_bg nc-bold\">jeune</span> ; le <span class=\"nc-pink_bg\">décès du</span> <span class=\"nc-pink_bg nc-bold\">conjoint</span> est aussi un facteur cité par le Collège.</li></ul></div>"},{"i":"a2439c8f9632","n":144,"o":"144-2","u":"Étiologies","t":"Connaître les facteurs de risque de complications du deuil","q":"Quels facteurs personnels et sociaux rechercher chez une personne endeuillée très isolée ?","a":"<div class=\"notion-course\"><ul><li>Antécédents psychiatriques, relation d’attachement, <span class=\"nc-yellow_bg\">répétition de deuil</span> et difficultés d’ajustement.</li><li>Culpabilité, manque de compréhension, <span class=\"nc-brown_bg\">manque de soutien social</span>, précarité ou absence de rituels.</li></ul></div>"},{"i":"19874422a32f","n":144,"o":"144-2","u":"Étiologies","t":"Connaître les facteurs de risque de complications du deuil","q":"Pourquoi « deuil récent » et « deuil prolongé » ne doivent-ils pas être confondus dans l’évaluation du risque ?","a":"<div class=\"notion-course\"><ul><li>La récence seule ne diagnostique pas un <span class=\"nc-yellow_bg\">deuil prolongé</span>.</li><li>Elle n’empêche pas une urgence : le risque suicidaire est particulièrement augmenté dans les premiers jours.</li></ul></div>"},{"i":"ea1286605b57","n":144,"o":"144-3","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’un deuil normal et pathologique","q":"Quel traitement proposer pour le seul deuil normal, sans trouble psychiatrique associé ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-green_bg\">Écoute empathique</span>, explications, soutien et mobilisation des ressources ; suivi selon les besoins.</li><li>Pas d’antidépresseur ni de psychotrope systématique pour le seul deuil normal.</li></ul></div>"},{"i":"0331c48bdaf5","n":144,"o":"144-3","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’un deuil normal et pathologique","q":"Quel traitement spécifique proposer devant un deuil prolongé invalidant ?","a":"<div class=\"notion-course\"><ul><li>Psychothérapie ciblée, notamment de type <span class=\"nc-green_bg nc-bold\">thérapie comportementale et cognitive</span>.</li><li>Rechercher et traiter séparément les comorbidités ; orienter vers une prise en charge spécialisée.</li></ul></div>"},{"i":"9a6c387e721a","n":144,"o":"144-3","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’un deuil normal et pathologique","q":"Un EDC sévère survient après un décès. Le contexte de deuil change-t-il le principe du traitement ?","a":"<div class=\"notion-course\"><ul><li>Non : même prise en charge qu’un EDC hors deuil.</li><li>Antidépresseur et psychothérapie selon indication, avis psychiatrique rapide, évaluation et prise en charge du risque suicidaire.</li></ul></div>"},{"i":"7e143cf19c6c","n":144,"o":"144-3","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’un deuil normal et pathologique","q":"Après une perte périnatale, faut-il attendre un deuil prolongé pour proposer un accompagnement ?","a":"<div class=\"notion-course\"><ul><li>Non : proposer dès les besoins exprimés un soutien individualisé aux parents.</li><li>Ne pas minimiser la perte ; inclure soutien social, fratrie et grands-parents selon la situation.</li></ul></div>"},{"i":"05990e8a1ae9","n":144,"o":"144-3","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’un deuil normal et pathologique","q":"Une personne endeuillée présente une intention suicidaire immédiate avec moyen accessible. Quelle priorité ?","a":"<div class=\"notion-course\"><ul><li>Protection immédiate, ne pas la laisser seule, sécuriser les moyens dangereux et organiser les soins urgents.</li><li>Évaluation clinique et psychiatrique ; hospitalisation selon le risque et le cadre légal.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d941812a92b7e05e60d437c5?pvs=204","reviewedAt":"2026-10-14","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","algorithms":2,"sddStatus":"Liens item–SDD et attendus des pages de situations vérifiés directement dans LiSA EDN 2026 le 14/10/2026. Correspondance documentaire ; couverture partielle précisée dans le cours.","lisaSituations":[{"number":237,"title":"Décès","url":"https://livret.uness.fr/lisa/2026/D%C3%A9c%C3%A8s_SDD-237","source":"LiSA EDN 2026","verifiedInLisa":true,"reviewedAt":"2026-10-14","expectedSkillsReviewed":true,"focus":"Accompagner l’annonce avec empathie, écouter les proches et repérer les facteurs de risque de deuil pathologique."},{"number":330,"title":"Accompagnement global d’un aidant","url":"https://livret.uness.fr/lisa/2026/Accompagnement_global_d%27un_aidant_SDD-330","source":"LiSA EDN 2026","verifiedInLisa":true,"reviewedAt":"2026-10-14","expectedSkillsReviewed":true,"focus":"Évaluer le vécu, la charge et la souffrance de l’aidant ; repérer ses besoins médicaux, psychologiques et sociaux et proposer un soutien."}],"lisaItemUrl":"https://livret.uness.fr/lisa/2026/Deuil_normal_et_pathologique","sddScope":"La fiche travaille le deuil et le soutien des proches. Le constat de décès, les démarches administratives et l’ensemble des besoins de l’aidant relèvent d’autres enseignements."},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d941812a92b7e05e60d437c5?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf#page=136","label":"CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e éd. 2024, item 144, p.135–138 ↗"},{"href":"https://www.psychiatry.org/patients-families/prolonged-grief-disorder","label":"American Psychiatric Association · Deuil prolongé, critères DSM-5-TR et soins, révision août 2025 ↗"},{"href":"https://onlinelibrary.wiley.com/doi/full/10.1002/wps.20823","label":"Prigerson et al. · Validation des critères DSM-5-TR du deuil prolongé, World Psychiatry 2021 ↗"},{"href":"https://www.psychiatry.org/getmedia/b68a5776-f88c-45c7-9535-fd219d7aa5cb/APA-DSM5TR-Update-September-2025.pdf","label":"American Psychiatric Association · Mises à jour du DSM-5-TR, compilation septembre 2025 ↗"},{"href":"https://www.ameli.fr/medecin/sante-prevention/pathologies/episode-depressif-caracterise-adulte","label":"Assurance maladie · Épisode dépressif caractérisé de l’adulte, recommandations HAS, décembre 2025 ↗"}]};
